import{sample,render,angles,values,overlapCases}from'./clock.mjs';
const $=s=>document.querySelector(s),state={...sample};
const fields=[['round','現在ラウンド',0,12,1,'gold'],['firstTime','先攻の残り時',0,12,1,'red'],['secondTime','後攻の残り時',0,12,1,'green'],['firstGrowth','先攻のそだち',0,100,5,'red'],['secondGrowth','後攻のそだち',0,100,5,'green']];
$('#overlap-presets').innerHTML=overlapCases.map(c=>`<button data-preset="${c.id}">${c.label}</button>`).join('');
$('#sliders').innerHTML=fields.map(([id,label,min,max,step,tone])=>`<label for="${id}" data-tone="${tone}">${label}<output id="${id}-out">${state[id]}</output><input id="${id}" type="range" aria-label="${label}" min="${min}" max="${max}" step="${step}" value="${state[id]}"></label>`).join('');
function update(){const opts={palette:$('#palette').value,profile:$('#profile').value,markers:$('#markers').checked};$('#live').innerHTML=render(state,opts);$('#overlap-gallery').innerHTML=overlapCases.map(c=>`<figure>${render({...state,...c.state},opts)}<figcaption>${c.label} · 金${c.state.round} / 赤${c.state.firstTime} / 緑${c.state.secondTime}</figcaption></figure>`).join('');$('#growth').innerHTML=render(state,{...opts,crop:'growth'});$('#end-detail').innerHTML=render(state,{...opts,crop:'end'});for(const[k]of fields){$('#'+k).value=state[k];$('#'+k+'-out').value=state[k];}$('#end').value=state.end;const labels=['ラウンド','先攻の残り時','後攻の残り時','先攻のそだち','後攻のそだち','終了ラウンド'],v=values(state),a=angles(state);$('#values').innerHTML=v.map((n,i)=>`<span>${labels[i]} ${n}${i===0&&n===0?'（準備）':i===0&&n===12?'（拡張候補）':i>0&&i<3&&n===0?'（0）':i>0&&i<3&&n===12?'（最大）':i===3||i===4?n===100?'（100到達）':n===0?'（0）':'':''}</span>`).join('');$('#angle-table').innerHTML=v.map((n,i)=>`<tr><td>${labels[i]}</td><td>${n}</td><td>${a[i].toFixed(1)}°</td><td>${i<3?(a[i]/30)+' / 12':i<5?(a[i]/18)+' / 20':({10:'右下 X',11:'左下 XI',12:'真上 XII'}[n])}</td></tr>`).join('');$('#status').textContent='全6針が指定目盛りに一致。'+(state.end>10||state.round>10?' XI・XIIは拡張候補の表示試験です。':' 通常ゴールはX。')+(state.round>state.end?' 現在値が終了設定を超えています（表示比較用）。':'');}
for(const[k]of fields)$('#'+k).addEventListener('input',e=>{state[k]=+e.target.value;update();});$('#end').addEventListener('change',e=>{state.end=+e.target.value;update();});for(const id of ['palette','profile','markers'])$('#'+id).addEventListener('change',update);
$('#reset').onclick=()=>{Object.assign(state,sample);update();};$('#overlap').onclick=()=>{Object.assign(state,{round:10,firstTime:10,secondTime:10});update();};$('#endpoints').onclick=()=>{Object.assign(state,{round:0,firstTime:0,secondTime:12,firstGrowth:0,secondGrowth:100});update();};update();

for(const button of document.querySelectorAll('[data-preset]'))button.onclick=()=>{Object.assign(state,overlapCases.find(c=>c.id===button.dataset.preset).state);update();};
